<?php
declare(strict_types=1);
require __DIR__.'/bootstrap.php';require_once __DIR__.'/../includes/marketplace.php';
if(clevo_env('APP_ENV')!=='testing'||!preg_match('/^clevo_security_test_[a-f0-9]{12}$/D',clevo_env('DB_DATABASE','')??''))exit(2);
$db=clevo_connect_database();if(strcasecmp(realpath($db->query('SELECT @@datadir d')->fetch_assoc()['d'])?:'',realpath(__DIR__.'/../.security-test/mysql')?:'!')!==0)exit(2);
$actor=function(string $role)use($db):int{$x=bin2hex(random_bytes(5));clevo_stmt($db,"INSERT INTO user (UserName,Email,PhoneNumber,Password,Role,AccountStatus,EmailVerifiedAt) VALUES (?,?,?,? ,?,'active',UTC_TIMESTAMP())",'sssss',[$x,$x.'@logistics.invalid','079'.random_int(1000000,9999999),password_hash(bin2hex(random_bytes(16)),PASSWORD_DEFAULT),$role]);return (int)$db->insert_id;};
$customer=$actor('customer');$stranger=$actor('customer');$owner=$actor('owner');$driver=$actor('driver');$driver2=$actor('driver');
clevo_stmt($db,"INSERT INTO stations (UserID,Name,admin_status,Status,Has_Delivery,BookingCapacity,HomeCapacity,OpeningTime,ClosingTime) VALUES (?,'Logistics','approved','Active',1,1000,1000,'00:00','00:00')",'i',[$owner]);$station=(int)$db->insert_id;clevo_stmt($db,'UPDATE user SET StationID=? WHERE UserID IN (?,?)','iii',[$station,$driver,$driver2]);
$service=clevo_market_service($db,$owner,$station,0,['name_ar'=>'غسيل','name_en'=>'Wash','price'=>'2.00','duration'=>30,'is_pickup'=>true]);clevo_stmt($db,'INSERT INTO wallet (UserID,Balance) VALUES (?,100),(?,0)','ii',[$customer,$owner]);
$body=['service_ids'=>[$service],'service_location'=>'delivery','booking_date'=>gmdate('Y-m-d',time()+86400*20),'booking_time'=>'10:00','latitude'=>31.95,'longitude'=>35.91];$job=clevo_create_booking($db,$customer,$station,$body,bin2hex(random_bytes(16)))['booking_id'];clevo_market_assign($db,$owner,$job,$driver);clevo_pay_booking($db,$customer,$job,'wallet',false,bin2hex(random_bytes(16)));
rejects(fn()=>clevo_delivery_tracking($db,$stranger,$job),'Other customer cannot track a booking','not_found');rejects(fn()=>clevo_delivery_tracking($db,$driver2,$job),'Unassigned driver cannot track a booking','not_found');
check(clevo_delivery_tracking($db,$customer,$job)['location']===null,'No fabricated driver marker before dispatch');
rejects(fn()=>clevo_delivery_advance($db,$driver,$job,'arrived_pickup'),'Stages cannot be skipped','invalid_transition');
clevo_delivery_advance($db,$driver,$job,'accepted');clevo_delivery_advance($db,$driver,$job,'heading_pickup');$view=clevo_delivery_tracking($db,$driver,$job);
$sample=['assignment_id'=>$view['assignment_id'],'sequence'=>1,'latitude'=>31.95,'longitude'=>35.91,'accuracy_m'=>12,'captured_at'=>gmdate('Y-m-d\TH:i:s\Z')];
check(clevo_delivery_location($db,$driver,$job,$sample)['stored'],'Active assignment stores timestamped accurate sample');check(clevo_delivery_location($db,$driver,$job,$sample)['duplicate'],'Location replay is idempotent without duplicate records');
rejects(fn()=>clevo_delivery_location($db,$driver,$job,array_replace($sample,['latitude'=>32])),'Same sequence cannot change coordinates','location_sequence_conflict');
rejects(fn()=>clevo_delivery_location($db,$driver,$job,array_replace($sample,['sequence'=>2,'assignment_id'=>$view['assignment_id']+1])),'Old/different assignment cannot post samples','assignment_changed');
rejects(fn()=>clevo_delivery_location($db,$driver,$job,array_replace($sample,['sequence'=>2,'capture_mode'=>'background'])),'Background collection needs separate approval','background_tracking_not_approved');
rejects(fn()=>clevo_delivery_location($db,$driver,$job,array_replace($sample,['captured_at'=>gmdate('Y-m-d\TH:i:s\Z',time()-300)])),'Offline backlog older than the limit is rejected','location_outside_time_window');
check(clevo_delivery_tracking($db,$customer,$job)['location_state']==='fresh','Customer reads fresh active GPS with accuracy');
clevo_delivery_advance($db,$driver,$job,'arrived_pickup');rejects(fn()=>clevo_delivery_advance($db,$driver,$job,'vehicle_collected'),'Driver cannot self-assert customer handoff','handoff_confirmation_required');
$code=clevo_delivery_issue_confirmation($db,$customer,$job,'pickup',bin2hex(random_bytes(16)));$wrong=$code['confirmation_code']==='100000'?'100001':'100000';
rejects(fn()=>clevo_delivery_confirm($db,$driver,$job,'pickup',$wrong,bin2hex(random_bytes(16))),'Wrong handoff code is rejected','invalid_or_expired_confirmation');
check((int)clevo_stmt($db,'SELECT Attempts FROM delivery_confirmations WHERE AssignmentID=?','i',[$view['assignment_id']])->get_result()->fetch_assoc()['Attempts']===1,'Invalid-code attempt commits despite request failure');
clevo_delivery_confirm($db,$driver,$job,'pickup',$code['confirmation_code'],bin2hex(random_bytes(16)));rejects(fn()=>clevo_delivery_confirm($db,$driver,$job,'pickup',$code['confirmation_code'],bin2hex(random_bytes(16))),'Consumed handoff cannot be replayed','invalid_transition');
clevo_delivery_advance($db,$driver,$job,'arrived_station');check(!clevo_delivery_tracking($db,$customer,$job)['sharing_allowed'],'Driver location is paused during station work');
rejects(fn()=>clevo_delivery_advance($db,$driver,$job,'service_completed'),'Only station owner can confirm service completion','forbidden_transition');
clevo_delivery_advance($db,$owner,$job,'service_completed');clevo_delivery_advance($db,$driver,$job,'returning_vehicle');
$return=clevo_delivery_issue_confirmation($db,$customer,$job,'delivery',bin2hex(random_bytes(16)));clevo_delivery_confirm($db,$driver,$job,'delivery',$return['confirmation_code'],bin2hex(random_bytes(16)));
check(clevo_delivery_tracking($db,$customer,$job)['location']===null,'Completed job never exposes retained GPS');
rejects(fn()=>clevo_delivery_location($db,$driver,$job,array_replace($sample,['sequence'=>2])),'Terminal assignment rejects new GPS');
check(clevo_stmt($db,'SELECT Driver_Lat FROM booking WHERE BookingID=?','i',[$job])->get_result()->fetch_assoc()['Driver_Lat']===null,'Terminal transition clears compatibility GPS cache');
check(clevo_delivery_purge($db)['gps_records_deleted']>=1,'Retention cleanup removes completed-job GPS without deleting booking history');
check((int)clevo_stmt($db,'SELECT COUNT(*) n FROM delivery_events WHERE BookingID=?','i',[$job])->get_result()->fetch_assoc()['n']===9,'Every assignment/stage has accountable immutable history');
finish_tests('Driver/logistics suite');
